from rdkit import Chem
from rdkit.Chem import rdDistGeom
import numpy as np, math

els = ['V','N','N','C','C','S','C','C','S','C','C','S']  # 0 V,1 Nnit,2 Nam, arms a(3,4,5) b(6,7,8) c(9,10,11)
N = len(els)
mol = Chem.RWMol()
for e in els: mol.AddAtom(Chem.Atom(e))
B = Chem.BondType
bonds = [(0,1,B.TRIPLE),(0,2,B.SINGLE),
         (0,5,B.SINGLE),(0,8,B.SINGLE),(0,11,B.SINGLE),
         (2,3,B.SINGLE),(2,6,B.SINGLE),(2,9,B.SINGLE),
         (3,4,B.SINGLE),(6,7,B.SINGLE),(9,10,B.SINGLE),
         (4,5,B.SINGLE),(7,8,B.SINGLE),(10,11,B.SINGLE)]
for i,j,t in bonds: mol.AddBond(i,j,t)
mol = mol.GetMol()
mol.UpdatePropertyCache(strict=False)

r0 = {}
def setbond(i,j,d):
    if i>j: i,j=j,i
    r0[(i,j)] = d
for i,j,_ in bonds:
    pass
setbond(0,1,1.62); setbond(0,2,2.20)
for s in (5,8,11): setbond(0,s,2.40)
for c in (3,6,9): setbond(2,c,1.47)
for a,b in ((3,4),(6,7),(9,10)): setbond(a,b,1.54)
for a,b in ((4,5),(7,8),(10,11)): setbond(a,b,1.82)

def bl(i,j):
    if i>j: i,j=j,i
    return r0[(i,j)]

BIG=80.0
lo = np.zeros((N,N)); hi = np.full((N,N), BIG)
np.fill_diagonal(hi,0.0)
def setb(i,j,l,h):
    if i==j: return
    if i>j: i,j=j,i
    lo[i,j]=max(lo[i,j],l); hi[i,j]=min(hi[i,j],h)

# 1-2
for (i,j),d in r0.items():
    w = 0.10 if (i==0 or j==0) else 0.05
    setb(i,j,d-w,d+w)
# 1-3 from angles
angles = []
for s in (5,8,11):
    angles += [(1,0,s,90.0),(2,0,s,90.0)]
for a,b in ((5,8),(5,11),(8,11)): angles.append((a,0,b,120.0))
angles.append((1,0,2,180.0))
for c in (3,6,9): angles.append((0,2,c,109.5))
for a,b in ((3,6),(3,9),(6,9)): angles.append((a,2,b,109.5))
for cc,ss in ((3,4),(6,7),(9,10)): angles.append((2,cc,ss,109.5))
for cc,ss in ((4,5),(7,8),(10,11)): angles.append((3 if cc==4 else (6 if cc==7 else 9), cc, ss, 109.5))
for ss,cc in ((5,4),(8,7),(11,10)): angles.append((0,ss,cc,109.5))
for (i,c,j,deg) in angles:
    th = math.radians(deg); ri=bl(i,c); rj=bl(j,c)
    d = math.sqrt(ri*ri+rj*rj-2*ri*rj*math.cos(th))
    setb(i,j,d-0.20,d+0.20)

# clash lower bounds for still-unconstrained heavy pairs
cov = {'V':1.53,'N':0.71,'C':0.76,'S':1.05}
for i in range(N):
    for j in range(i+1,N):
        if hi[i,j] >= BIG-1 and lo[i,j]==0.0:
            setb(i,j, 0.80*(cov[els[i]]+cov[els[j]]), BIG)

bm = np.zeros((N,N))
for i in range(N):
    for j in range(N):
        if i<j: bm[i,j]=hi[i,j]
        elif i>j: bm[i,j]=lo[j,i]

ok = rdDistGeom.EmbedMolecule(mol, boundsMatrix=bm, useRandomCoords=True,
                              randomSeed=11, maxAttempts=5000)
print('embed status:', ok)
conf = mol.GetConformer()
P = np.array([[conf.GetAtomPosition(i).x,conf.GetAtomPosition(i).y,conf.GetAtomPosition(i).z] for i in range(N)])
def d(i,j): return float(np.linalg.norm(P[i]-P[j]))
print('V-Nnit %.3f  V-Nam %.3f'%(d(0,1),d(0,2)))
print('V-S', [round(d(0,s),3) for s in (5,8,11)])
print('S-S', [round(d(a,b),3) for a,b in ((5,8),(5,11),(8,11))])
print('Nnit-Nam %.3f'%d(1,2))
print('N-C', [round(d(2,c),3) for c in (3,6,9)], ' C-C',[round(d(a,b),3) for a,b in ((3,4),(6,7),(9,10))],' C-S',[round(d(a,b),3) for a,b in ((4,5),(7,8),(10,11))])

# ---- add H analytically to the six CH2 carbons ----
def add_H2(pos, ci, n1, n2, rCH=1.09):
    C=pos[ci]; a=pos[n1]-C; b=pos[n2]-C
    a=a/np.linalg.norm(a); b=b/np.linalg.norm(b)
    c=float(np.dot(a,b)); c=max(-0.999999,min(0.999999,c))
    m=a+b; m=m/np.linalg.norm(m)
    n=np.cross(a,b); nn=np.linalg.norm(n)
    if nn<1e-6:
        # degenerate: pick any perpendicular
        t=np.array([1.0,0,0]);
        if abs(a[0])>0.9: t=np.array([0.0,1.0,0])
        n=np.cross(a,t); nn=np.linalg.norm(n)
    n=n/nn
    alpha=-(1.0/3.0)/math.sqrt((1.0+c)/2.0)
    beta2=1.0-alpha*alpha
    beta=math.sqrt(max(beta2,0.0))
    h1=alpha*m+beta*n; h2=alpha*m-beta*n
    h1=h1/np.linalg.norm(h1); h2=h2/np.linalg.norm(h2)
    return [C+rCH*h1, C+rCH*h2]

heavy=[list(P[i]) for i in range(N)]
atoms=[els[i] for i in range(N)]
for ci,n1,n2 in [(3,2,4),(4,3,5),(6,2,7),(7,6,8),(9,2,10),(10,9,11)]:
    for hp in add_H2(P,ci,n1,n2):
        atoms.append('H'); heavy.append(list(hp))
M=len(atoms)
with open('guess.xyz','w') as f:
    f.write(f"{M}\n[V(N)(N(CH2CH2S)3)] guess (RDKit-DG + analytic H)\n")
    for sym,p in zip(atoms,heavy):
        f.write(f"{sym:2s} {p[0]:12.6f} {p[1]:12.6f} {p[2]:12.6f}\n")
print('wrote guess.xyz atoms=',M)
